task.vi:
Cho biết chương trình sau in ra những gì:
#include <iostream>
using namespace std;
int main() {
   unsigned int y = 0;
   unsigned int x = 1;
   unsigned int total = 0;
   while ( x <= 10 ) {
      y = x * x;
      cout << y << endl;
      total += y;
      ++x;
   }
   cout << "Total is " << total << endl;
}

