example.code:
#include <iostream>
#include <iomanip>

int main() {
    int miles{0};
    int totalMiles{0};
    int totalGallons{0};

    std::cout << std::fixed << std::setprecision(6);

    while (std::cin >> miles && miles != -1) {
        int gallons{0};
        if (!(std::cin >> gallons) || gallons <= 0) {
            break;
        }

        double mpgTrip = static_cast<double>(miles) / gallons;
        totalMiles += miles;
        totalGallons += gallons;
        double totalMpg = static_cast<double>(totalMiles) / totalGallons;

        std::cout << "MPG this trip: " << mpgTrip << "\n";
        std::cout << "Total MPG: " << totalMpg << "\n";
    }

    return 0;
}
